test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 42500, total: 42500 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21 },
    ],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 42500 + 1960, total: 42500 + 1960 });
});

test('invoiceTotals with different VAT rates', () => {
  const invoice = {
